import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './command-palette.css';

type Command = { id: string; label: string; group: string; run: () => void };
// The supplied package inventory has no documented CommandPalette.
// This local adapter uses native dialog/listbox semantics plus available primitives.
// The application supplies permitted commands and persists recent IDs.
export function CommandPalette({ open, commands, recentIds, onRecentChange, onClose }: {
 open: boolean; commands: Command[]; recentIds: string[];
 onRecentChange: (ids: string[]) => void; onClose: () => void;
}) {
 const dialog = useRef<HTMLDialogElement>(null);
 const input = useRef<HTMLInputElement>(null);
 const base = useId();
 const [query, setQuery] = useState('');
 const [active, setActive] = useState(0);
 const groups = useMemo(() => {
   const result = new Map<string, Command[]>();
   const recent = query.trim() ? [] : recentIds.map(id => commands.find(c => c.id === id)).filter((c): c is Command => !!c);
   if (recent.length) result.set('Recent', recent);
   const seen = new Set(recent.map(c => c.id));
   commands.filter(c => !seen.has(c.id) && c.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).forEach(c => {
     const key = c.group === 'Recent' ? 'Other commands' : c.group;
     result.set(key, [...(result.get(key) ?? []), c]);
   });
   return [...result.entries()];
 }, [commands, recentIds, query]);
 const visible = groups.flatMap(([, items]) => items);
 const index = Math.min(active, Math.max(0, visible.length - 1));
 useEffect(() => {
   const node = dialog.current!;
   if (open && !node.open) { setQuery(''); setActive(0); node.showModal(); input.current?.focus(); }
   else if (!open && node.open) node.close();
 }, [open]);
 useEffect(() => { document.getElementById(base + '-option-' + index)?.scrollIntoView({ block: 'nearest' }); }, [base, index]);
 function execute(command: Command) {
   onRecentChange([command.id, ...recentIds.filter(id => id !== command.id)].slice(0, 8));
   onClose(); command.run();
 }
 return <dialog ref={dialog} className="kui-layout command-dialog" aria-labelledby={base + '-title'}
   onCancel={e => { e.preventDefault(); onClose(); }}>
   <DialogHeader><h2 id={base + '-title'}>Commands</h2></DialogHeader>
   <div className="command-body">
     <label htmlFor={base + '-input'}>Find a command</label>
     <input ref={input} id={base + '-input'} role="combobox" autoComplete="off"
       aria-autocomplete="list" aria-expanded="true" aria-controls={base + '-results'}
       aria-activedescendant={visible.length ? base + '-option-' + index : undefined}
       value={query} onChange={e => { setQuery(e.target.value); setActive(0); }}
       onKeyDown={e => {
         if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
           e.preventDefault(); if (visible.length) setActive((index + (e.key === 'ArrowDown' ? 1 : -1) + visible.length) % visible.length);
         } else if (e.key === 'Enter' && visible[index]) { e.preventDefault(); execute(visible[index]); }
       }} />
     <div id={base + '-results'} role="listbox" aria-label="Matching commands">
       {groups.map(([group, items], groupIndex) => <div role="group" aria-labelledby={base + '-group-' + groupIndex} key={group}>
         <div id={base + '-group-' + groupIndex}>{group}</div>
         {items.map(command => {
           const row = visible.indexOf(command);
           return <div role="option" id={base + '-option-' + row} aria-selected={row === index} key={command.id}
             onMouseDown={e => e.preventDefault()} onMouseMove={() => setActive(row)} onClick={() => execute(command)}>
             {row === index && <span aria-hidden="true">› </span>}{command.label}
           </div>;
         })}
       </div>)}
     </div>
     {!visible.length && <EmptyState><p>No commands match “{query}”. Try another search.</p></EmptyState>}
     <div role="status" className="sr-only">{visible.length} commands available.</div>
   </div>
   <footer><button type="button" onClick={onClose}>Close</button></footer>
 </dialog>;
}

