.command-dialog { padding: 0; width: min(36rem, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem); overflow: hidden; }
.command-dialog[open] { display: flex; flex-direction: column; }
.command-dialog::backdrop { background: rgb(0 0 0 / .45); }
.command-body { padding: var(--kui-space-4, 1rem); overflow: auto; min-height: 0; }
.command-body input { box-sizing: border-box; width: 100%; min-height: 2.75rem; }
.command-body [role=option] { min-height: 2.75rem; display: flex; align-items: center; overflow-wrap: anywhere; cursor: pointer; }
.command-body [aria-selected=true] { outline: 2px solid currentColor; outline-offset: -2px; font-weight: bold; }
.command-dialog footer { flex-shrink: 0; padding: var(--kui-space-4, 1rem); }
.command-dialog :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
